  //_________________________________________________________________________________
  FTC1q2qM::FTC1q2qM():
    DoubleExpression()
  {
  }
  double FTC1q2qM::LocalLocal(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    return (-4 + Dn(0,x,true)*Dn(0,z,true) + Dn(1,x,true) + Dn(1,z,true))*(NC - NCi);
  };
  double FTC1q2qM::LocalSingular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    return (Dn(1,z) + Dn(0,z)*Dn(0,x,true))*(NC - NCi);
  };
  double FTC1q2qM::LocalRegular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    const double omzi = 1. / ( 1 - z );
    const double lz = log(z);
    const double lomz = log(1 - z);
    return -0.5*((NC - NCi)*(-1 + z + (1 + z)*Dn(0,x,true) + (1 + z)*lomz + lz + z*lz - 2*lz*omzi));
  };
  double FTC1q2qM::SingularLocal(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    return (Dn(1,x) + Dn(0,x)*Dn(0,z,true))*(NC - NCi);
  };
  double FTC1q2qM::SingularSingular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    return Dn(0,x)*Dn(0,z)*(NC - NCi);
  };
  double FTC1q2qM::SingularRegular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    return -0.5*((1 + z)*Dn(0,x)*(NC - NCi));
  };
  double FTC1q2qM::RegularLocal(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    const double omxi = 1. / ( 1 - x );
    const double lx = log(x);
    const double lomx = log(1 - x);
    return -0.5*((NC - NCi)*(-1 + x + (1 + x)*Dn(0,z,true) + (1 + x)*lomx - lx - x*lx + 2*lx*omxi));
  };
  double FTC1q2qM::RegularSingular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    return -0.5*((1 + x)*Dn(0,z)*(NC - NCi));
  };
  double FTC1q2qM::RegularRegular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    return (1 + x*z)*(NC - NCi);
  };

  //_________________________________________________________________________________
  FTC1q2gM::FTC1q2gM():
    DoubleExpression()
  {
  }
  double FTC1q2gM::LocalRegular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    const double zi = 1. / z;
    const double lz = log(z);
    const double lomz = log(1 - z);
    return ((NC - NCi)*(z - 2*lz + z*lz + 2*lz*zi + Dn(0,x,true)*(-2 + z + 2*zi) + lomz*(-2 + z + 2*zi)))/2.;
  };
  double FTC1q2gM::SingularRegular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    const double zi = 1. / z;
    return (Dn(0,x)*(NC - NCi)*(-2 + z + 2*zi))/2.;
  };
  double FTC1q2gM::RegularRegular(double const& x, double const& z) const
  {
    const double NCi = 1. / NC;
    const double zi = 1. / z;
    return -0.5*((NC - NCi)*(-2 + 2*x*(-1 + z) + (1 + x)*zi));
  };

  //_________________________________________________________________________________
  FTC1g2qM::FTC1g2qM():
    DoubleExpression()
  {
  }
  double FTC1g2qM::RegularLocal(double const& x, double const& z) const
  {
    const double x2 = x * x;
    const double lx = log(x);
    const double lomx = log(1 - x);
    return x - lx/2. + x*lx - x2 - lx*x2 + Dn(0,z,true)*(0.5 - x + x2) + lomx*(0.5 - x + x2);
  };
  double FTC1g2qM::RegularSingular(double const& x, double const& z) const
  {
    const double x2 = x * x;
    return Dn(0,z)*(0.5 - x + x2);
  };
  double FTC1g2qM::RegularRegular(double const& x, double const& z) const
  {
    const double x2 = x * x;
    const double zi = 1. / z;
    return -1 + 2*x - 2*x2 + zi/2. - x*zi + x2*zi;
  };

